<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ ?>
<div class="actions"><div><span class="status">ADM</span><h1>Status do CRM</h1><p class="meta">Defina as opções exibidas no cadastro dos contatos.</p></div><a href="<?= $escape($basePath) ?>/statuses/create">Novo status</a></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="table-responsive"><table><thead><tr><th>Status</th><th>Ordem</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($statuses as $item):?><tr><td><span class="tag-badge" style="--tag-color:<?= $escape($item['color']) ?>"><?= $escape($item['name']) ?></span></td><td><?= $escape($item['sort_order']) ?></td><td><?= (int)$item['is_active']===1?'Ativo':'Inativo' ?></td><td><a href="<?= $escape($basePath) ?>/statuses/<?= $escape($item['id']) ?>/edit">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
